  `email` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci DEFAULT NULL,
  `cart_contents` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci,
  `cart_total` decimal(10,2) DEFAULT NULL,
  `session_id` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `other_fields` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci,
  `order_status` enum('normal','abandoned','completed','lost') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT 'normal',
  `unsubscribed` tinyint(1) DEFAULT '0',
  `coupon_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci DEFAULT NULL,
  `time` datetime DEFAULT NULL,
  `original_cart_total` decimal(10,2) DEFAULT NULL,
  `order_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`,`session_id`),
  UNIQUE KEY `session_id_UNIQUE` (`session_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_520_ci;
