INSERT INTO `wp_options` VALUES (1969,'zipwp_user_business_details','a:12:{s:20:\"business_description\";s:2410:\"Crea una plataforma web de lujo para \"CRISTAMAR - Eventos & Producción de Autor\", especializada en logística de alta precisión, producción audiovisual de alta gama y diseño de experiencias exclusivas en Bogotá y la Sabana (Chía, Sopó, Tenjo, Cajicá). La estética del sitio debe ser de lujo, elegante y moderna, utilizando un fondo oscuro (azul noche/negro mate) con acentos dorados y tipografías serifas sofisicadas.Estructura y secciones requeridas:Encabezado y Hero Section:Barra superior de cobertura regional y contacto rápido. Menú principal: Inicio, Nosotros, Servicios, Locaciones, Cotizador VIP y botón destacado \"Simular Presupuesto\". Título principal impactante: \"Reinventamos la Producción de Eventos en Bogotá y la Sabana\" con subtítulo sobre logística de precisión y tecnología interactiva. Botones de acción principales: \"Cotizar mi Evento en Tiempo Real\" y \"Agendar Asesoría VIP\". Métricas de Confianza y Historia:Bloque de estadísticas: +150 eventos ejecutados, 99% satisfacción y 100% transparencia presupuestal. Sección \"Historia de los Fundadores\" (Marlon Romero & Sara Vargas) resaltando el trato cercano, la coordinación milimétrica y la pasión por los eventos. Enfoque Corporativo, BTL y Producción Técnica:Tarjeta explicativa con \"Precisión Cronometrada al Segundo & Rider Técnico de Clase Mundial\". Destacar rigor minuto a minuto, infraestructura audiovisual pro (pantallas LED, micrófonos Shure, streaming sin latencia) y gestión BTL de alto impacto. Catálogo de Servicios y Locaciones Filtables:Tarjetas de servicios filtrables por categorías: Corporativo & BTL, Bodas & Sociales y Producción Técnica. Sección de \"Locaciones Exclusivas\" (haciendas coloniales, palacios de cristal, reservas campestres) con capacidad de personas, características clave y botón para cotizar. Cotizador Inteligente / Simulador de Presupuesto:Módulo interactivo de \"Cotizador VIP en Tiempo Real\" donde el usuario configure tipo de evento, número de invitados con barra deslizante y servicios adicionales (catering, iluminación, sonido) con cálculo estimado automático en COP. Prueba Social y Pie de Página:Carrusel/tarjetas de testimonios con calificación de 5 estrellas de directores de mercadeo y parejas. Botón flotante directo a WhatsApp y pie de página completo con enlaces de navegación rápida, zonas de cobertura e información de contacto VIP.\";s:13:\"business_name\";s:26:\"https://eventocapital.com/\";s:14:\"business_email\";s:31:\"ad.sara.vargas@unilatina.edu.co\";s:16:\"business_address\";s:2:\"SA\";s:14:\"business_phone\";s:10:\"3015754093\";s:17:\"business_category\";s:5:\"Event\";s:22:\"business_category_name\";s:5:\"Event\";s:13:\"image_keyword\";a:12:{i:0;s:22:\"audiovisual production\";i:1;s:15:\"event logistics\";i:2;s:12:\"luxury event\";i:3;s:18:\"exclusive location\";i:4;s:20:\"wedding coordination\";i:5;s:14:\"event planning\";i:6;s:30:\"high-end audiovisual equipment\";i:7;s:11:\"LED screens\";i:8;s:16:\"precision timing\";i:9;s:13:\"planning team\";i:10;s:19:\"elegant table setup\";i:11;s:23:\"detailed event proposal\";}s:6:\"images\";a:16:{i:0;a:11:{s:2:\"id\";s:8:\"17206160\";s:3:\"url\";s:75:\"https://images.pexels.com/photos/17206160/pexels-photo-17206160.jpeg?w=1280\";s:13:\"optimized_url\";s:100:\"https://images.pexels.com/photos/17206160/pexels-photo-17206160.jpeg?auto=compress&cs=tinysrgb&h=350\";s:11:\"description\";s:99:\"Beautifully decorated indoor wedding reception with elegant table settings and floral arrangements.\";s:10:\"author_url\";s:42:\"https://www.pexels.com/@bertellifotografia\";s:11:\"author_name\";s:16:\"Matheus Bertelli\";s:11:\"orientation\";s:9:\"landscape\";s:6:\"engine\";s:6:\"pexels\";s:10:\"engine_url\";s:18:\"https://pexels.com\";s:4:\"slug\";s:35:\"rustic-wedding-dining-room-17206160\";s:17:\"download_location\";s:0:\"\";}i:1;a:11:{s:2:\"id\";s:8:\"17057029\";s:3:\"url\";s:75